func (this *testMainClass) initInnerBody(ch chan any, exchangeId any, symbolArgv any, methodArgv any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	this.ParseCliArgsAndProps()
	if EvalTruthy(this.RequestTests) && EvalTruthy(this.ResponseTests) {

		PanicOnError((<-this.RunStaticRequestTestsAsync(exchangeId, symbolArgv)))

		PanicOnError((<-this.RunStaticResponseTestsAsync(exchangeId, symbolArgv)))

		ch <- true
		return nil
	}
	if EvalTruthy(this.ResponseTests) {

		PanicOnError((<-this.RunStaticResponseTestsAsync(exchangeId, symbolArgv)))

		ch <- true
		return nil
	}
	if EvalTruthy(this.StaticWsTests) {

		PanicOnError((<-this.RunStaticWsTestsAsync(exchangeId, symbolArgv)))

		ch <- true
		return nil
	}
	if EvalTruthy(this.RequestTests) {

		PanicOnError((<-this.RunStaticRequestTestsAsync(exchangeId, symbolArgv))) // symbol here is the testname

		ch <- true
		return nil
	}
	if EvalTruthy(this.IdTests) {

		PanicOnError((<-this.RunBrokerIdTestsAsync()))

		ch <- true
		return nil
	}
	var newLine string = "\n"
	Dump(newLine+""+newLine+""+"[INFO] TESTING ", this.Ext, map[string]any{
		"exchange": exchangeId,
		"symbol":   symbolArgv,
		"method":   methodArgv,
		"isWs":     this.WsTests,
		"useProxy": GetCliArgValue("--useProxy"),
	}, newLine)
	var exchangeArgs map[string]any = map[string]any{
		"verbose":         this.Verbose,
		"debug":           this.Debug,
		"enableRateLimit": true,
		"timeout":         30000,
	}
	var exchange ccxt.ICoreExchange = InitExchange(exchangeId, exchangeArgs, this.WsTests)
	SetExchangeProp(exchange, "fetchHistoryCacheSize", 5)
	if EvalTruthy(exchange.GetAlias()) {
		Dump(this.AddPadding("[INFO] skipping alias", 25))
		ExitScript(0)
	}

	PanicOnError((<-this.ImportFilesAsync(exchange)))
	// ensure test files are found & filled
	Assert((len(ObjectKeys(this.TestFiles)) > 0), "Test files were not loaded")
	this.ExpandSettings(exchange)
	this.CheckIfSpecificTestIsChosen(methodArgv)

	PanicOnError((<-this.StartTestAsync(exchange, symbolArgv)))
	ExitScript(0) // needed to be explicitly finished for WS tests

	ch <- true // required for c#
	return nil
}
func (this *testMainClass) CheckIfSpecificTestIsChosen(methodArgv any) {
	if !IsEqual(methodArgv, nil) {
		var testFileNames []string = ObjectKeys(this.TestFiles)
		var possibleMethodNames []string = Split(methodArgv, ",") // i.e. `test.ts binance fetchBalance,fetchDeposits`
		if len(possibleMethodNames) >= 1 {
			for i := 0; i < len(testFileNames); i++ {
				var testFileName string = GetValue(testFileNames, i).(string)
				for j := 0; j < len(possibleMethodNames); j++ {
					var methodName string = GetValue(possibleMethodNames, j).(string)
					methodName = strings.Replace(methodName, "()", "", 1)
					if IsEqual(testFileName, methodName) {
						AppendToArray(&this.OnlySpecificTests, testFileName)
					}
				}
			}
		}
	}
}
