	if EvalTruthy(IsSync()) {
		this.TestFiles = GetTestFilesSync(properties, this.WsTests)
	} else {

		this.TestFiles = (<-GetTestFiles(properties, this.WsTests))
		PanicOnError(this.TestFiles)
	}

	ch <- true
	return nil
