func (this *testMainClass) testMethodBody(ch chan any, methodName any, exchange ccxt.ICoreExchange, args any, isPublic any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// todo: temporary skip for c#
	if (GetIndexOf(methodName, "OrderBook") >= 0) && (this.Ext == "cs") {
		AddElementToObject(exchange.GetOptions(), "checksum", false)
	}
	// todo: temporary skip for php
	if (GetIndexOf(methodName, "OrderBook") >= 0) && (this.Ext == "php") {

		ch <- true
		return nil
	}
	var skippedPropertiesForMethod any = this.GetSkips(exchange, methodName)
	var isLoadMarkets bool = (methodName == "loadMarkets")
	var isFetchCurrencies bool = (methodName == "fetchCurrencies")
	var isProxyTest bool = (methodName == this.ProxyTestFileName)
	var isConstructorTest bool = (methodName == "afterConstruct")
	var isFeatureTest bool = (methodName == "features")
	// if this is a private test, and the implementation was already tested in public, then no need to re-test it in private test (exception is fetchCurrencies, because our approach in base exchange)
	if !EvalTruthy(isPublic) && (InOp(this.CheckedPublicTests, methodName)) && !isFetchCurrencies {

		ch <- true
		return nil
	}
	var skipMessage any = nil
	var supportedByExchange bool = (InOp(exchange.GetHas(), methodName)) && (!IsEqual(GetValue(exchange.GetHas(), methodName), nil)) && (!IsEqual(GetValue(exchange.GetHas(), methodName), false))
	if !isLoadMarkets && ((GetArrayLength(this.OnlySpecificTests) > 0) && (!IsEqual(exchange.InArray(methodName, this.OnlySpecificTests), true))) {
		skipMessage = "[INFO] IGNORED_TEST"
	} else if !isLoadMarkets && !supportedByExchange && !isProxyTest && !isFeatureTest && !isConstructorTest {
		skipMessage = "[INFO] UNSUPPORTED_TEST" // keep it aligned with the longest message
	} else if IsString(skippedPropertiesForMethod) {
		skipMessage = "[INFO] SKIPPED_TEST"
	} else if !(InOp(this.TestFiles, methodName)) {
		skipMessage = "[INFO] UNIMPLEMENTED_TEST"
	}
	var name any = exchange.GetId()
	// the TESTING / TESTING DONE / TESTING FAILED markers are dumped unconditionally
	// (not gated on `--info`) because run-tests.js diffs them on RUNTEST_TIMED_OUT to
	// report which method(s) were still running when the per-exchange timeout fired
	// exceptionally for `loadMarkets` call, we call it before it's even checked for "skip" as we need it to be called anyway (but can skip "test.loadMarket" for it)
	if isLoadMarkets {
		Dump(this.AddPadding("[INFO] TESTING", 25), name, methodName)

		PanicOnError((<-exchange.LoadMarketsAsync(true)))
		Dump(this.AddPadding("[INFO] TESTING DONE", 25), name, methodName)
	}
	if !IsEqual(skipMessage, nil) && (skipMessage != "") {
		if EvalTruthy(this.Info) {
			Dump(this.AddPadding(skipMessage, 25), name, methodName)
		}

		ch <- true
		return nil
	}
	var argsStringified any = Add(Add("(", exchange.Json(args)), ")") // args.join() breaks when we provide a list of symbols or multidimensional array; "args.toString()" breaks bcz of "array to string conversion"
	Dump(this.AddPadding("[INFO] TESTING", 25), name, methodName, argsStringified)
	if EvalTruthy(IsSync()) {
		CallMethodSync(this.TestFiles, methodName, exchange, skippedPropertiesForMethod, args)
	} else {

		PanicOnError((<-CallMethod(this.TestFiles, methodName, exchange, skippedPropertiesForMethod, args)))
	}
	Dump(this.AddPadding("[INFO] TESTING DONE", 25), name, methodName)
	// add to the list of successed tests
	if EvalTruthy(isPublic) {
		AddElementToObject(this.CheckedPublicTests, methodName, true)
	}

	ch <- true
	return nil
}
func (this *testMainClass) GetSkips(exchange ccxt.ICoreExchange, methodName any) any {
	var finalSkips map[string]any = map[string]any{}
	// check the exact method (i.e. `fetchTrades`) and language-specific (i.e. `fetchTrades.php`)
	var methodNames []any = []any{methodName, Add(Add(methodName, "."), this.Ext)}
	for i := 0; i < len(methodNames); i++ {
		var mName any = func() any {
			if i >= 0 && i < len(methodNames) {
				return DerefScalar(methodNames[i])
			}
			return nil
		}()
		if InOp(this.SkippedMethods, mName) {
			// if whole method is skipped, by assigning a string to it, i.e. "fetchOrders":"blabla"
			if IsString(GetValue(this.SkippedMethods, mName)) {
				return GetValue(this.SkippedMethods, mName)
			} else {
				finalSkips = exchange.DeepExtend(finalSkips, GetValue(this.SkippedMethods, mName))
			}
		}
	}
	// get "object-specific" skips
	var objectSkips map[string]any = map[string]any{
		"orderBook":          []any{"fetchOrderBook", "fetchOrderBooks", "fetchL2OrderBook", "watchOrderBook", "watchOrderBookForSymbols"},
		"ticker":             []any{"fetchTicker", "fetchTickers", "watchTicker", "watchTickers"},
		"trade":              []any{"fetchTrades", "watchTrades", "watchTradesForSymbols"},
		"ohlcv":              []any{"fetchOHLCV", "watchOHLCV", "watchOHLCVForSymbols"},
		"ledger":             []any{"fetchLedger", "fetchLedgerEntry"},
		"depositWithdraw":    []any{"fetchDepositsWithdrawals", "fetchDeposits", "fetchWithdrawals"},
		"depositWithdrawFee": []any{"fetchDepositWithdrawFee", "fetchDepositWithdrawFees"},
	}
	var objectNames []string = ObjectKeys(objectSkips)
	for i := 0; i < len(objectNames); i++ {
		var objectName string = GetValue(objectNames, i).(string)
		var objectMethods any = objectSkips[objectName]
		if EvalTruthy(exchange.InArray(methodName, objectMethods)) {
			// if whole object is skipped, by assigning a string to it, i.e. "orderBook":"blabla"
			if (InOp(this.SkippedMethods, objectName)) && (IsString(GetValue(this.SkippedMethods, objectName))) {
				return GetValue(this.SkippedMethods, objectName)
			}
			var extraSkips any = exchange.SafeDict(this.SkippedMethods, objectName, map[string]any{})
			finalSkips = exchange.DeepExtend(finalSkips, extraSkips)
		}
	}
	// extend related skips
	// - if 'timestamp' is skipped, we should do so for 'datetime' too
	// - if 'bid' is skipped, skip 'ask' too
	if (func() bool { _, ok := finalSkips["timestamp"]; return ok }()) && !(func() bool { _, ok := finalSkips["datetime"]; return ok }()) {
		finalSkips["datetime"] = finalSkips["timestamp"]
	}
	if (func() bool { _, ok := finalSkips["bid"]; return ok }()) && !(func() bool { _, ok := finalSkips["ask"]; return ok }()) {
		finalSkips["ask"] = finalSkips["bid"]
	}
	if (func() bool { _, ok := finalSkips["baseVolume"]; return ok }()) && !(func() bool { _, ok := finalSkips["quoteVolume"]; return ok }()) {
		finalSkips["quoteVolume"] = finalSkips["baseVolume"]
	}
	return finalSkips
}
func (this *testMainClass) TestSafeAsync(methodName any, exchange ccxt.ICoreExchange, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.testSafeBody(ch, methodName, exchange, optionalArgs...)
	return ch
}
func (this *testMainClass) testSafeBody(ch chan any, methodName any, exchange ccxt.ICoreExchange, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	// `testSafe` method does not throw an exception, instead mutes it. The reason we
	// mute the thrown exceptions here is because we don't want to stop the whole
	// tests queue if any single test-method fails. Instead, they are echoed with
	// formatted message "[TEST_FAILURE] ..." and that output is then regex-matched by
	// run-tests.js, so the exceptions are still printed out to console from there.
	var args []any = GetArgAnySlice(optionalArgs, 0, []any{})
	_ = args
	var isPublic bool = GetArgBool(optionalArgs, 1, false)
	_ = isPublic
	var maxRetries int = 3
	var argsStringified any = exchange.Json(args) // args.join() breaks when we provide a list of symbols or multidimensional array; "args.toString()" breaks bcz of "array to string conversion"
	for i := 0; i < maxRetries; i++ {

		{
			func(this *testMainClass) (ret_ any) {
				defer func() {
					if ex := recover(); ex != nil {
						if ex == "break" {
							return
						}
						ret_ = func(this *testMainClass) any {
							// catch block:
							// close the TESTING marker (pairs with the dump in `testMethod`), so on a
							// RUNTEST_TIMED_OUT run-tests.js doesn't misreport a failed method as hung
							Dump(this.AddPadding("[INFO] TESTING FAILED", 25), exchange.GetId(), methodName)
							var e any = GetRootException(ex)
							var isLoadMarkets bool = (methodName == "loadMarkets")
							var isAuthError bool = (IsInstance(e, AuthenticationError))
							var isNotSupported bool = (IsInstance(e, NotSupported))
							var isOperationFailed bool = (IsInstance(e, OperationFailed)) // includes "DDoSProtection", "RateLimitExceeded", "RequestTimeout", "ExchangeNotAvailable", "OperationFailed", "InvalidNonce", ...
							var lastUrlMsg any = func() any {
								if EvalTruthy(this.WsTests) {
									return ""
								}
								return Add(Add(" (Last url: ", this.GetLastRequestUrl(exchange)), " )")
							}()
							if isOperationFailed {
								// if last retry was gone with same `tempFailure` error, then let's eventually return false
								if i == maxRetries-1 {
									var isOnMaintenance bool = (IsInstance(e, OnMaintenance))
									var isExchangeNotAvailable bool = (IsInstance(e, ExchangeNotAvailable))
									var shouldFail any = nil
									var retSuccess any = nil
									if isLoadMarkets {
										// if "loadMarkets" does not succeed, we must return "false" to caller method, to stop tests continual
										retSuccess = false
										// we might not break exchange tests, if exchange is on maintenance at this moment
										if isOnMaintenance {
											shouldFail = false
										} else {
											shouldFail = true
										}
									} else {
										// for any other method tests:
										if isExchangeNotAvailable && !isOnMaintenance {
											// break exchange tests if "ExchangeNotAvailable" exception is thrown, but it's not maintenance
											shouldFail = true
											retSuccess = false
										} else {
											// in all other cases of OperationFailed, show Warning, but don't mark test as failed
											shouldFail = false
											retSuccess = true
										}
									}
									// output the message
									var failType string = func() string {
										if EvalTruthy(shouldFail) {
											return "[TEST_FAILURE]"
										}
										return "[TEST_WARNING]"
									}()
									Dump(failType, exchange.GetId(), methodName, argsStringified, lastUrlMsg, "Method could not be tested due to a repeated Network/Availability issues", " | ", ExceptionMessage(e))

									ch <- retSuccess
									chSent = true
									return nil
								} else {
									// wait and retry again
									// (increase wait time on every retry)

									PanicOnError((<-exchange.Sleep((i + 1) * 1000)))
								}
							} else {
								// if it's loadMarkets, then fail test, because it's mandatory for tests
								if isLoadMarkets {
									Dump("[TEST_FAILURE]", exchange.GetId(), methodName, argsStringified, lastUrlMsg, "Exchange can not load markets", ExceptionMessage(e))

									ch <- false
									chSent = true
									return nil
								}
								// if the specific arguments to the test method throws "NotSupported" exception
								// then let's don't fail the test
								if isNotSupported {
									if EvalTruthy(this.Info) {
										Dump("[INFO] NOT_SUPPORTED", exchange.GetId(), methodName, argsStringified, lastUrlMsg, ExceptionMessage(e))
									}

									ch <- true
									chSent = true
									return nil
								}
								// If public test faces authentication error, we don't break (see comments under `testSafe` method)
								if (isPublic == true) && isAuthError {
									if EvalTruthy(this.Info) {
										// todo - turn into warning
										Dump("[INFO]", exchange.GetId(), methodName, argsStringified, lastUrlMsg, "Authentication problem for public method", ExceptionMessage(e))
									}

									ch <- true
									chSent = true
									return nil
								} else {
									Dump("[TEST_FAILURE]", exchange.GetId(), methodName, argsStringified, lastUrlMsg, ExceptionMessage(e))

									ch <- false
									chSent = true
									return nil
								}
							}
							return nil
						}(this)
					}
				}()
				// try block:

				PanicOnError((<-this.TestMethodAsync(methodName, exchange, args, isPublic)))

				ch <- true
				chSent = true
				return nil

			}(this)
			if chSent {
				return nil
			}

		}
	}

	ch <- true
	return nil
}
func (this *testMainClass) GetLastRequestUrl(exchange ccxt.ICoreExchange) any {
	var fetchCache any = exchange.GetFetchCache()
	var url any = ""
	if GetArrayLength(fetchCache) > 0 {
		var lastEntry map[string]any = MapTyped(GetValue(fetchCache, GetArrayLength(fetchCache)-1))
		var lastRequest any = lastEntry["request"]
		if !IsEqual(lastRequest, nil) {
			url = exchange.SafeString(lastRequest, "url", "")
		}
	}
	return url
}
