func (this *testMainClass) runPrivateTestsBody(ch chan any, exchange ccxt.ICoreExchange, symbols any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// mirrors runPublicTests: the caller always passes the selected symbols as an array
	// (even a CLI-provided symbol arrives as a one-element array), and private tests run
	// on the primary symbol per market type
	var symbol any = GetValue(symbols, 0)
	if !IsEqual(exchange.CheckRequiredCredentials(false), true) {
		Dump("[INFO] Skipping private tests", "Keys not found")

		ch <- true
		return nil
	}
	var code any = this.GetExchangeCode(exchange)
	// if (exchange.GetdeepExtendedTest()) {
	//     await test ('InvalidNonce', exchange, symbol);
	//     await test ('OrderNotFound', exchange, symbol);
	//     await test ('InvalidOrder', exchange, symbol);
	//     await test ('InsufficientFunds', exchange, symbol, balance); // danger zone - won't execute with non-empty balance
	// }
	var tests map[string]any = map[string]any{
		"signIn":                         []any{},
		"fetchBalance":                   []any{},
		"fetchAccounts":                  []any{},
		"fetchTransactionFees":           []any{},
		"fetchTradingFees":               []any{},
		"fetchStatus":                    []any{},
		"fetchOrders":                    []any{symbol},
		"fetchOpenOrders":                []any{symbol},
		"fetchClosedOrders":              []any{symbol},
		"fetchMyTrades":                  []any{symbol},
		"fetchLeverageTiers":             []any{[]any{symbol}},
		"fetchLedger":                    []any{code},
		"fetchTransactions":              []any{code},
		"fetchDeposits":                  []any{code},
		"fetchWithdrawals":               []any{code},
		"fetchTransfers":                 []any{code},
		"fetchBorrowInterest":            []any{code, symbol},
		"cancelAllOrders":                []any{symbol},
		"fetchCanceledOrders":            []any{symbol},
		"fetchMarginModes":               []any{symbol},
		"fetchPosition":                  []any{symbol},
		"fetchDeposit":                   []any{code},
		"createDepositAddress":           []any{code},
		"fetchDepositAddress":            []any{code},
		"fetchDepositAddresses":          []any{code},
		"fetchDepositAddressesByNetwork": []any{code},
		"fetchBorrowRateHistory":         []any{code},
		"fetchLedgerEntry":               []any{code},
	}
	if EvalTruthy(GetCliArgValue("--fundedTests")) {
		tests["createOrder"] = []any{symbol}
	}
	if EvalTruthy(this.WsTests) {
		tests = map[string]any{
			"watchBalance":   []any{code},
			"watchMyTrades":  []any{symbol},
			"watchOrders":    []any{symbol},
			"watchPosition":  []any{symbol},
			"watchPositions": []any{symbol},
		}
	}
	var market any = exchange.Market(symbol)
	var isSpot any = GetValue(market, "spot")
	if !EvalTruthy(this.WsTests) {
		if isSpot == true {
			tests["fetchCurrencies"] = []any{}
		} else {
			// derivatives only
			tests["fetchPositions"] = []any{symbol} // this test fetches all positions for 1 symbol
			tests["fetchPosition"] = []any{symbol}
			tests["fetchPositionRisk"] = []any{symbol}
			tests["setPositionMode"] = []any{symbol}
			tests["setMarginMode"] = []any{symbol}
			tests["fetchOpenInterestHistory"] = []any{symbol}
			tests["fetchFundingRateHistory"] = []any{symbol}
			tests["fetchFundingHistory"] = []any{symbol}
		}
	}
	// const combinedTests = exchange.GetdeepExtend() (this.publicTests, privateTests);

	PanicOnError((<-this.RunTestsAsync(exchange, tests, false)))

	ch <- true // required in c#
	return nil
}
func (this *testMainClass) TestProxiesAsync(exchange ccxt.ICoreExchange) <-chan any {
	ch := make(chan any, 1)
	go this.testProxiesBody(ch, exchange)
	return ch
}
func (this *testMainClass) testProxiesBody(ch chan any, exchange ccxt.ICoreExchange) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	// these tests should be synchronously executed, because of conflicting nature of proxy settings
	var proxyTestName any = this.ProxyTestFileName
	// todo: temporary skip for sync py
	if (this.Ext == "py") && EvalTruthy(IsSync()) {

		ch <- true
		return nil
	}
	// try proxy several times
	var maxRetries int = 3
	var exceptionMessageString any = nil
	for j := 0; j < maxRetries; j++ {

		{
			func(this *testMainClass) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *testMainClass) any {
							// catch block:
							exceptionMessageString = ExceptionMessage(e)

							PanicOnError((<-exchange.Sleep(j * 1000)))
							return nil
						}(this)
					}
				}()
				// try block:

				PanicOnError((<-this.TestMethodAsync(proxyTestName, exchange, []any{}, true)))

				ch <- true // if successfull, then end the test
				chSent = true
				return nil

			}(this)
			if chSent {
				return nil
			}

		}
	}
	// if exception was set, then throw it
	if !IsEqual(exceptionMessageString, nil) {
		var errorMessage any = Add(Add(Add("[TEST_FAILURE] Failed ", proxyTestName), " : "), exceptionMessageString)
		// temporary comment the below, because c# transpilation failure
		// throw new Exchange Error (errorMessage.toString ());
		Dump(Add("[TEST_WARNING]", errorMessage))
	}

	ch <- true
	return nil
}
func (this *testMainClass) CheckConstructor(exchange ccxt.ICoreExchange) {
	// todo: this might be moved in base tests later
	if IsEqual(exchange.GetId(), "binance") {
		Assert(IsEqual(exchange.GetHostname(), nil) || IsEqual(exchange.GetHostname(), ""), "binance.com hostname should be empty")
		Assert(IsEqual(GetValue(GetValue(exchange.GetUrls(), "api"), "public"), "https://api.binance.com/api/v3"), Add("https://api.binance.com/api/v3 does not match: ", GetValue(GetValue(exchange.GetUrls(), "api"), "public")))
		Assert((InOp(GetValue(GetValue(exchange.GetApi(), "sapi"), "get"), "lending/union/account")), "SAPI should contain the endpoint lending/union/account, "+JsonStringify(GetValue(GetValue(exchange.GetApi(), "sapi"), "get")))
	} else if IsEqual(exchange.GetId(), "binanceus") {
		Assert(IsEqual(exchange.GetHostname(), "binance.us"), Add("binance.us hostname does not match ", exchange.GetHostname()))
		Assert(IsEqual(GetValue(GetValue(exchange.GetUrls(), "api"), "public"), "https://api.binance.us/api/v3"), Add("https://api.binance.us/api/v3 does not match: ", GetValue(GetValue(exchange.GetUrls(), "api"), "public")))
	}
}
