func (this *testMainClass) testReturnResponseHeadersBody(ch chan any, exchange ccxt.ICoreExchange) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	if !IsEqual(exchange.GetId(), "binance") {

		ch <- false // this test is only for binance exchange for now
		return nil
	}
	exchange.SetReturnResponseHeaders(true)

	ticker := (<-exchange.FetchTickerAsync("BTC/USDT"))
	PanicOnError(ticker)
	var info map[string]any = MapTyped(GetValue(ticker, "info"))
	var headers any = info["responseHeaders"]
	var headersKeys []string = ObjectKeys(headers)
	Assert((len(headersKeys) > 0), "Response headers should not be empty")
	var headerValues []any = ObjectValues(headers)
	Assert((len(headerValues) > 0), "Response headers values should not be empty")
	exchange.SetReturnResponseHeaders(false)

	ch <- true
	return nil
}
func (this *testMainClass) StartTestAsync(exchange ccxt.ICoreExchange, symbolArgv any) <-chan any {
	ch := make(chan any, 1)
	go this.startTestBody(ch, exchange, symbolArgv)
	return ch
}
func (this *testMainClass) startTestBody(ch chan any, exchange ccxt.ICoreExchange, symbolArgv any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	// we do not need to test aliases
	if IsEqual(exchange.GetAlias(), true) {

		ch <- true
		return nil
	}
	this.CheckConstructor(exchange)
	// await this.testReturnResponseHeaders (exchange);
	if EvalTruthy(this.Sandbox) || (IsEqual(GetExchangeProp(exchange, "sandbox"), true)) {
		exchange.SetSandboxMode(true)
	}
	this.TestHasProps(exchange)

	{
		func(this *testMainClass) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *testMainClass) any {
						// catch block:
						if !EvalTruthy(IsSync()) {

							PanicOnError((<-Close(exchange)))
						}
						panic(e)

					}(this)
				}
			}()
			// try block:

			result := (<-this.LoadExchangeAsync(exchange))
			PanicOnError(result)
			if !(result == true) {
				if !EvalTruthy(IsSync()) {

					PanicOnError((<-Close(exchange)))
				}

				ch <- true
				chSent = true
				return nil
			}
			// if (exchange.Getid() === 'binance') {
			//     // we test proxies functionality just for one random exchange on each build, because proxy functionality is not exchange-specific, instead it's all done from base methods, so just one working sample would mean it works for all ccxt exchanges
			//     // await this.testProxies (exchange);
			// }

			PanicOnError((<-this.TestExchangeAsync(exchange, symbolArgv)))
			if !EvalTruthy(IsSync()) {

				PanicOnError((<-Close(exchange)))
			}
			return nil
		}(this)
		if chSent {
			return nil
		}

	}

	ch <- true // required in c#
	return nil
}
func (this *testMainClass) TestHasProps(exchange ccxt.ICoreExchange) {
	var watchOrderBookSkips any = this.GetSkips(exchange, "watchOrderBook")
	var fetchOrderBookSkips any = this.GetSkips(exchange, "fetchOrderBook")
	// ensure with hardcoded list of required methods
	if EvalTruthy(this.WsTests) && (!IsEqual(exchange.SafeBool(exchange.GetHas(), "watchOrderBook", false), true)) && !IsString(watchOrderBookSkips) {
		Dump("[TEST_FAILURE] Method \"watchOrderBook\" is not set in \"has\", please check the \"has\" property of exchange")
		ExitScript(1)
	} else if !EvalTruthy(this.WsTests) && (!IsEqual(exchange.SafeBool(exchange.GetHas(), "fetchOrderBook", false), true)) && !IsString(fetchOrderBookSkips) {
		Dump("[TEST_FAILURE] Method \"fetchOrderBook\" is not set in \"has\", please check the \"has\" property of exchange")
		ExitScript(1)
	}
}
func (this *testMainClass) AssertStaticError(cond any, message any, calculatedOutput any, storedOutput any, optionalArgs ...any) {
	//  -----------------------------------------------------------------------------
	//  --- Init of static tests functions------------------------------------------
	//  -----------------------------------------------------------------------------
	// Fast path: the error message is only consumed when the assertion
	// fails, but `jsonStringify` of the (possibly large) computed and
	// stored outputs happens here on EVERY leaf/branch comparison.
	// That is cheap in JS but O(tree²) in the Rust port (each level
	// re-serialises its whole subtree) — it made `--responseTests`
	// take minutes. Bail out before stringifying when the check holds.
	key := GetArg(optionalArgs, 0, nil)
	_ = key
	if EvalTruthy(cond) {
		return
	}
	var calculatedString string = JsonStringify(calculatedOutput)
	var storedString string = JsonStringify(storedOutput)
	var errorMessage any = message
	if !IsEqual(key, nil) {
		errorMessage = Add(Add("[", key), "]")
	}
	errorMessage = Add(errorMessage, " computed: "+storedString+" stored: "+calculatedString)
	Assert(cond, errorMessage)
}
